head.script:
scwin.qnaId;
scwin.gEmpNo = js_emp_no;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        getId = $c.frame.path("../").fn_getId;
        scwin.qnaId = getId();
        await scwin.read();
        const sbmOptions = {
            id : "sbm_dts_input",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_input=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30331.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Cave_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cave_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30331.btn_Cave_onclick" });
    }
};

/**
 * @method
 * @name btn_Cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30331.btn_Cancel_onclick" });
    }
};

/**
 * @method
 * @name dts_readOfficialInfo_OnLoadCompleted
 * @description dts_readOfficialInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_readOfficialInfo_OnLoadCompleted = function(rowcount) {
    try {
        scwin.gEmpNo = dts_readOfficialInfo.getCellData(1, "WRTR_EMP_NO");
        // alert(js_emp_no +'=='+ gEmpNo);

        // 등록자만 삭제/수정버튼이 보이도록 수정 : 2008.08.07 이연숙대리 요청
        if (js_emp_no === scwin.gEmpNo) {
            btn_save.show("");
            btn_delete.show("");
        } else {
            btn_save.hide();
            btn_delete.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30331.dts_readOfficialInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_input_OnFail
 * @description input On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_input_OnFail = async function() {
    try {
        await $c.win.alert(trs_input);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30331.trs_input_OnFail" });
    }
};

/**
 * @method
 * @name trs_input_OnSuccess
 * @description input On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_input_OnSuccess = async function() {
    try {
        await $c.win.alert("답변을 저장하였습니다");
        frame.opener.fn_search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30331.trs_input_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description 공문 개별조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    // 공문 개별조회
    const sbmOptions = {
        id : "sbm_dts_qnaInfo",
        action : "/qnaResult.do",
        ref : "",
        target : "dts_qnaInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description 공문수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 공문수정
    if ($c.stf.getStringSize(ans_contn.Text) > 2000) {
        await $c.win.alert("[ 답변내용 ] 의 최대입력은 [ 2000 ] byte 입니다.    \n\n[ " + $c.stf.getStringSize(ans_contn.Text) + " ] byte 입니다. 확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        ans_contn.focus();
        return false;
    }
    if (window.confirm("[저장]하시겠습니까?")) {
        dts_input.removeAll();
        dts_input.insertRow();
        dts_input.setCellData(dts_input.getRowPosition(), "EMP_NO", scwin.gEmpNo);
        dts_input.setCellData(dts_input.getRowPosition(), "ANS_CONTN", ans_contn.Text);
        dts_input.setCellData(dts_input.getRowPosition(), "QUES_ID", scwin.qnaId);
        trs_input.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_input",
            action : "/qnaResult.do",
            ref : "dts_input",
            target : "trs_input=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkMaxLength1
 * @description check Max Length1 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength1 = async function(obj, size, lbl) {
    let overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkMaxLength2
 * @description check Max Length2 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength2 = async function(obj, size, lbl) {
    let overLen = ($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
